        this.lastY = y;
        this.lastZ = z;
        this.lastYaw = yaw;
        this.lastPitch = pitch;
        this.lastMoveNanos = System.nanoTime();
        this.pendingX = x;
        this.pendingY = y;
        this.pendingZ = z;
        this.pendingYaw = yaw;
