    }

    void recordBroadcast(double x, double y, double z, float yaw, float pitch) {
        this.broadcastX = x;
        this.broadcastY = y;
        this.broadcastZ = z;
        this.broadcastYaw = yaw;
        this.broadcastPitch = pitch;
        this.broadcastValid = true;
    }

    double broadcastX() {
        return broadcastX;
    }

    double broadcastY() {
        return broadcastY;
    }

    double broadcastZ() {
        return broadcastZ;
    }

    float broadcastYaw() {
        return broadcastYaw;
    }

    float broadcastPitch() {
        return broadcastPitch;
    }

    static int floorChunk(double coordinate) {
        return Math.floorDiv((int) Math.floor(coordinate), 16);
    }

    static long chunkKey(int chunkX, int chunkZ) {
        return ((long) chunkX << 32) ^ (chunkZ & 0xFFFFFFFFL);
    }

    static UUID randomId() {
        return UUID.randomUUID();
    }
}

