package io.webcraft.bridge.ws;

import java.net.InetAddress;
import java.util.List;
import java.util.logging.Level;
import java.util.logging.Logger;

/**
 * Development-only harness: starts the dependency-free WebSocket server without Paper and echoes
 * every text message. Run it from the build output, connect with bridge/test-client/selftest.mjs,
 * then stop it. Not packaged into the plugin jar.
 */
public final class WsSelfTest {

    public static void main(String[] args) throws Exception {
        Logger logger = Logger.getLogger("WebCraftBridgeSelfTest");
        logger.setLevel(Level.ALL);
        WsServer server = new WsServer(
                new WsServer.Options(
                        InetAddress.getLoopbackAddress(),
                        0,
                        "/ws",
                        List.of("http://localhost:5174"),
                        true,
                        4
                ),
                new WsServer.Handler() {
                    @Override
                    public void onOpen(WsConnection connection) {
                        connection.sendText("{\"t\":\"welcome\"}");
                    }

                    @Override
                    public void onText(WsConnection connection, String message) {
                        connection.sendText(message);
                    }

                    @Override
                    public void onClose(WsConnection connection, int code, String reason) {
                        System.out.println("SELFTEST_CLOSE code=" + code + " reason=" + reason);
                    }
                },
                logger,
                () -> "{\"ok\":true,\"selftest\":true}"
        );
        int port = server.start();
        System.out.println("SELFTEST_PORT=" + port);
        System.out.flush();
        Thread.sleep(30_000L);
        server.stop();
    }
}

// Dependency-free check for the plugin's WebSocket layer.
// Usage: node selftest.mjs <port>
// Start WsSelfTest first (see README), then run this. Requires Node 22+ (global WebSocket/fetch).
const port = process.argv[2];
if (!port) {
  console.error("usage: node selftest.mjs <port>");
  process.exit(2);
}

const health = await fetch(`http://127.0.0.1:${port}/health`);
console.log("health", health.status, await health.text());

const ws = new WebSocket(`ws://127.0.0.1:${port}/ws`);
let welcome = false;
let echo = false;

const timeout = setTimeout(() => {
  console.error("FAIL: timeout");
  process.exit(1);
}, 5000);

ws.addEventListener("message", (event) => {
  console.log("recv", event.data);
  if (event.data.includes('"welcome"')) welcome = true;
  else if (event.data.includes('"t":"selftest"')) echo = true;
  if (welcome && echo) {
    clearTimeout(timeout);
    ws.close(1000, "selftest done");
    console.log("PASS websocket handshake, text frames, health endpoint");
    setTimeout(() => process.exit(0), 100);
  }
});

ws.addEventListener("open", () => {
  ws.send('{"t":"selftest","n":1}');
});

ws.addEventListener("error", (event) => {
  console.error("FAIL: websocket error", event);
  process.exit(1);
});

ws.addEventListener("close", (event) => {
  if (!welcome || !echo) {
    clearTimeout(timeout);
    console.error("FAIL: closed early", event.code, event.reason);
    process.exit(1);
  }
});

